// ------------------------------------------------------------------ Chapter 4
function spec(reqs, files, by) {
  return [table(["Requirements covered", "Principal source files", "Developed by"], [[reqs, files, by]], [1800, 4726, 2500], { size: 20 }), spacer()];
}
function mod(no, name, purpose, funcs, impl, reqs, files, by) {
  return [
    h2(`4.${no} Module ${no}: ${name}`),
    p("**Purpose.** " + purpose),
    p("**Functional responsibilities.**", { spacing: { after: 40 } }),
    ...bullets(funcs),
    p("**Implementation.** " + impl),
    ...spec(reqs, files, by),
  ];
}

